import React, { useState } from 'react';
import { Package, DollarSign, User, PlusCircle, CheckCircle, BarChart3, ArrowLeft, AlertTriangle } from 'lucide-react';

// --- Mock Data tailored to Maria Rodriguez's Farm ---
const initialInventory = [
  { id: 1, name: 'Heirloom Tomatoes', stock: 35, unit: 'lbs', price: 3.50, status: 'In Stock' },
  { id: 2, name: 'Organic Kale', stock: 50, unit: 'bunches', price: 2.75, status: 'In Stock' },
  { id: 3, name: 'Honeycrisp Apples', stock: 8, unit: 'lbs', price: 2.25, status: 'Low Stock' },
  { id: 4, name: 'Rainbow Carrots', stock: 45, unit: 'bunches', price: 3.00, status: 'In Stock' },
  { id: 5, name: 'Sweet Corn', stock: 0, unit: 'ears', price: 0.75, status: 'Sold Out' },
  { id: 6, name: 'Free-Range Eggs', stock: 22, unit: 'dozen', price: 5.00, status: 'In Stock' },
];

const salesData = {
  today: 482.50,
  week: 1975.00,
  topSeller: 'Heirloom Tomatoes',
  weeklyTrend: [ {day: 'Mon', sales: 210}, {day: 'Tue', sales: 150}, {day: 'Wed', sales: 320}, {day: 'Thu', sales: 280}, {day: 'Fri', sales: 450}, {day: 'Sat', sales: 850}, {day: 'Sun', sales: 650} ]
};

// Helper component for status badges
const StatusBadge = ({ status }) => {
  const baseClasses = 'px-2 py-1 text-xs font-medium rounded-full';
  const statusClasses = {
    'In Stock': 'bg-green-100 text-green-800',
    'Low Stock': 'bg-yellow-100 text-yellow-800',
    'Sold Out': 'bg-red-100 text-red-800',
  };
  return <span className={`${baseClasses} ${statusClasses[status]}`}>{status}</span>;
};

// Main Prototype Component
export default function FarmstandAppPrototype() {
  const [currentScreen, setCurrentScreen] = useState('inventory');
  const [inventory, setInventory] = useState(initialInventory);
  const [newProduct, setNewProduct] = useState({ name: 'Golden Zucchini', price: '2.50', stock: '40', unit: 'lbs' });

  const handleAddProduct = () => {
    const newProductData = {
      id: inventory.length + 1,
      name: newProduct.name,
      stock: parseInt(newProduct.stock, 10),
      unit: newProduct.unit,
      price: parseFloat(newProduct.price),
      status: 'In Stock'
    };
    setInventory([newProductData, ...inventory]);
    setCurrentScreen('addProductSuccess');
  };

  const NavItem = ({ icon: Icon, label, screenName }) => (
    <button
      onClick={() => setCurrentScreen(screenName)}
      className={`flex items-center w-full px-4 py-3 text-left transition-colors duration-200 ${currentScreen === screenName ? 'bg-blue-50 text-blue-700 font-semibold' : 'text-gray-600 hover:bg-gray-100'}`}>
      <Icon className="w-5 h-5 mr-3" />
      <span>{label}</span>
    </button>
  );

  const Sidebar = () => (
    <div className="w-64 bg-white border-r border-gray-200 flex flex-col">
      <div className="p-4 border-b border-gray-200">
        <h1 className="text-xl font-bold text-gray-800">Farmstand Pro</h1>
        <p className="text-sm text-gray-500">Rodriguez Family Farm</p>
      </div>
      <nav className="flex-grow py-4 space-y-1">
        <NavItem icon={Package} label="Inventory" screenName="inventory" />
        <NavItem icon={DollarSign} label="Sales" screenName="sales" />
        <NavItem icon={User} label="Account" screenName="account" />
      </nav>
      <div className="p-4 border-t border-gray-200">
        <p className="text-sm font-medium text-gray-700">Maria Rodriguez</p>
        <a href="#" className="text-xs text-blue-600 hover:underline">Sign Out</a>
      </div>
    </div>
  );

  const InventoryScreen = () => (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800">Inventory</h2>
        <button onClick={() => setCurrentScreen('addProductForm')} className="flex items-center px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 transition-all duration-200 shadow-sm">
          <PlusCircle className="w-4 h-4 mr-2" />
          Add New Product
        </button>
      </div>
      <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded-r-md mb-6 flex items-start">
          <AlertTriangle className="h-5 w-5 text-yellow-500 mr-3 mt-0.5 flex-shrink-0" />
          <div>
              <p className="font-semibold text-yellow-800">Low Stock Alert</p>
              <p className="text-sm text-yellow-700">'Honeycrisp Apples' are running low. Add more stock before the Saturday market.</p>
          </div>
      </div>
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
        <table className="w-full text-sm text-left text-gray-600">
          <thead className="bg-gray-50 text-xs text-gray-700 uppercase tracking-wider">
            <tr>
              <th scope="col" className="px-6 py-3">Product Name</th>
              <th scope="col" className="px-6 py-3">Stock</th>
              <th scope="col" className="px-6 py-3">Price</th>
              <th scope="col" className="px-6 py-3">Status</th>
            </tr>
          </thead>
          <tbody>
            {inventory.map((item) => (
              <tr key={item.id} className="bg-white border-b hover:bg-gray-50">
                <td className="px-6 py-4 font-medium text-gray-900 whitespace-nowrap">{item.name}</td>
                <td className="px-6 py-4">{item.stock} {item.unit}</td>
                <td className="px-6 py-4">${item.price.toFixed(2)}</td>
                <td className="px-6 py-4"><StatusBadge status={item.status} /></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );

  const SalesScreen = () => (
     <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">Sales Dashboard</h2>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <h3 className="text-sm font-medium text-gray-500">Sales Today</h3>
          <p className="text-3xl font-bold text-gray-800 mt-1">${salesData.today.toFixed(2)}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <h3 className="text-sm font-medium text-gray-500">This Week's Total</h3>
          <p className="text-3xl font-bold text-gray-800 mt-1">${salesData.week.toFixed(2)}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <h3 className="text-sm font-medium text-gray-500">Top Seller</h3>
          <p className="text-3xl font-bold text-gray-800 mt-1">{salesData.topSeller}</p>
        </div>
      </div>
      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <h3 className="text-lg font-semibold text-gray-800 mb-4 flex items-center"><BarChart3 className="w-5 h-5 mr-2 text-blue-600"/>Weekly Sales Trend</h3>
          <div className="flex justify-between items-end h-48 space-x-2">
            {salesData.weeklyTrend.map(d => (
              <div key={d.day} className="flex-1 flex flex-col items-center justify-end">
                <div className="w-full bg-blue-500 hover:bg-blue-600 rounded-t-md transition-all duration-200" style={{ height: `${(d.sales / 1000) * 100}%` }}></div>
                <span className="text-xs text-gray-500 mt-2">{d.day}</span>
              </div>
            ))}
          </div>
      </div>
    </div>
  );

  const AccountScreen = () => (
    <div>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">Account Settings</h2>
      <div className="bg-white p-8 rounded-lg shadow-sm border border-gray-200 max-w-2xl">
        <div className="space-y-6">
          <div>
            <label className="block text-sm font-medium text-gray-700">Full Name</label>
            <input type="text" value="Maria Rodriguez" disabled className="mt-1 block w-full px-3 py-2 bg-gray-100 border border-gray-300 rounded-md shadow-sm" />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Email Address</label>
            <input type="email" value="maria.rodriguez@farm.local" disabled className="mt-1 block w-full px-3 py-2 bg-gray-100 border border-gray-300 rounded-md shadow-sm" />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700">Farm Name</label>
            <input type="text" value="Rodriguez Family Farm" disabled className="mt-1 block w-full px-3 py-2 bg-gray-100 border border-gray-300 rounded-md shadow-sm" />
          </div>
          <button className="px-4 py-2 text-sm font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700">Update Profile</button>
        </div>
      </div>
    </div>
  );

  const AddProductFormScreen = () => (
    <div>
       <button onClick={() => setCurrentScreen('inventory')} className="flex items-center text-sm text-gray-600 hover:text-gray-900 mb-4">
          <ArrowLeft className="w-4 h-4 mr-1" /> Back to Inventory
        </button>
      <h2 className="text-2xl font-bold text-gray-800 mb-6">Add New Product</h2>
      <div className="bg-white p-8 rounded-lg shadow-sm border border-gray-200 max-w-2xl">
        <div className="space-y-6">
          <div>
            <label htmlFor="productName" className="block text-sm font-medium text-gray-700">Product Name</label>
            <input type="text" id="productName" value={newProduct.name} onChange={(e) => setNewProduct({...newProduct, name: e.target.value})} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500" />
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label htmlFor="price" className="block text-sm font-medium text-gray-700">Price (per unit)</label>
              <div className="mt-1 relative rounded-md shadow-sm">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none"><span className="text-gray-500 sm:text-sm">$</span></div>
                <input type="text" id="price" value={newProduct.price} onChange={(e) => setNewProduct({...newProduct, price: e.target.value})} className="block w-full pl-7 pr-12 border-gray-300 rounded-md focus:ring-blue-500 focus:border-blue-500" />
              </div>
            </div>
             <div>
              <label htmlFor="unit" className="block text-sm font-medium text-gray-700">Unit</label>
              <select id="unit" value={newProduct.unit} onChange={(e) => setNewProduct({...newProduct, unit: e.target.value})} className="mt-1 block w-full pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-blue-500 focus:border-blue-500 sm:text-sm rounded-md">
                <option>lbs</option>
                <option>bunches</option>
                <option>each</option>
                <option>dozen</option>
              </select>
            </div>
          </div>
          <div>
            <label htmlFor="stock" className="block text-sm font-medium text-gray-700">Initial Stock Quantity</label>
            <input type="number" id="stock" value={newProduct.stock} onChange={(e) => setNewProduct({...newProduct, stock: e.target.value})} className="mt-1 block w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500" />
          </div>
          <div className="flex justify-end pt-4">
            <button onClick={() => setCurrentScreen('inventory')} className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-md hover:bg-gray-50 mr-3">Cancel</button>
            <button onClick={handleAddProduct} className="px-6 py-2 text-sm font-medium text-white bg-green-600 rounded-md hover:bg-green-700 transition-all duration-200 shadow-sm">Save Product</button>
          </div>
        </div>
      </div>
    </div>
  );

  const AddProductSuccessScreen = () => (
    <div className="flex flex-col items-center justify-center text-center max-w-lg mx-auto py-12">
      <CheckCircle className="w-16 h-16 text-green-500 mb-4" />
      <h2 className="text-2xl font-bold text-gray-800 mb-2">Product Added!</h2>
      <p className="text-gray-600 mb-6">'{newProduct.name}' has been successfully added to your inventory and is ready for sale.</p>
      <div className="bg-white border border-gray-200 rounded-lg p-4 w-full text-left mb-8">
        <p><span className="font-semibold">Name:</span> {newProduct.name}</p>
        <p><span className="font-semibold">Price:</span> ${parseFloat(newProduct.price).toFixed(2)} / {newProduct.unit}</p>
        <p><span className="font-semibold">Initial Stock:</span> {newProduct.stock} {newProduct.unit}</p>
      </div>
      <button onClick={() => setCurrentScreen('inventory')} className="px-6 py-2 font-medium text-white bg-blue-600 rounded-md hover:bg-blue-700 transition-all duration-200 shadow-sm">Return to Inventory</button>
    </div>
  );

  const renderScreen = () => {
    switch (currentScreen) {
      case 'inventory': return <InventoryScreen />;
      case 'sales': return <SalesScreen />;
      case 'account': return <AccountScreen />;
      case 'addProductForm': return <AddProductFormScreen />;
      case 'addProductSuccess': return <AddProductSuccessScreen />;
      default: return <InventoryScreen />;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 font-sans antialiased text-gray-900" style={{ fontFamily: "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" }}>
      <div className="flex h-screen">
        <Sidebar />
        <main className="flex-1 p-8 overflow-y-auto">
          <div className="max-w-7xl mx-auto">
            {renderScreen()}
          </div>
        </main>
      </div>
    </div>
  );
}
